 const tools=`<form id="explore-form" class="explorar-ferramentas"><label class="field busca-campo">Buscar estabelecimento ou descrição<span class="busca">${U.icone('explorar')}<input type="search" name="busca" value="${e(estado.busca)}" placeholder="Ex.: mercado, transporte…"></span></label><label class="field">Categoria<select name="categoria"><option value="">Todas as categorias</option>${cats.map(c=>`<option value="${e(c.chave)}" ${c.chave===estado.categoria?'selected':''}>${e(c.nome)}</option>`).join('')}</select></label><label class="field">Ordenar<select name="ordem"><option value="valor" ${estado.ordem==='valor'?'selected':''}>Maior valor</option><option value="data" ${estado.ordem==='data'?'selected':''}>Mais recentes</option></select></label><div class="actions"><button type="submit" class="primary">Aplicar</button>${U.botao('Limpar',()=>{estado.busca='';estado.categoria='';estado.pagina=0;render();},'ghost')}</div></form>`;
 const comparavel=!estado.drill?.referencias;
 const prior=comparavel?C.filtrar(dados[porCompra?'compras':'gastos_analiticos']||[],{...filtroLocal(),...C.periodoAnterior(fs)}):[];
