// Recorrências: primeiro o custo fixo e o que espera decisão; depois o calendário.
function recorrencias(){
 const fs=estado.filtros,rows=C.filtrar(dados.recorrencias_analiticas,fs,false),ativas=rows.filter(r=>r.estado==='ativa'),sugestoes=rows.filter(r=>r.estado==='sugestao'),future=C.parcelasFuturas(dados.transacoes_analiticas,fs);
 const anual=C.somar(ativas,'custo_anual_estimado_brl');
 const acoes=(r,id)=>`<div class="row-actions">${(id!=='ativa'?[['ativa','Confirmar no banco']]:[['encerrada','Encerrar no banco']]).concat(id!=='ignorada'?[['ignorada','Ignorar']]:[]).map(([estadoNovo,n],i)=>U.botao(n,()=>salvar({tipo:'recorrencia',instituicao:r.instituicao,estabelecimento:r.estabelecimento,estado:estadoNovo}),'small'+(id==='sugestao'&&i===0?' primary':i>0?' ghost':''),!api.podeEditar?'disabled':'')).join('')}</div>`;
 const mesCurto=m=>{const t=String(m??'').replace(/\D/g,'');return t.length>=6?C.mesBR(t.slice(0,4)+'-'+t.slice(4,6)):e(m??'—');};
 const observacao=r=>`${C.numero(r.meses_observados)} ${r.meses_observados===1?'mês':'meses'} · ${mesCurto(r.primeiro_mes)} → ${mesCurto(r.ultimo_mes)}`;
 const tabela=(id,compacta=false)=>U.tabela(['Estabelecimento / conta',...(compacta?[]:[{n:'Média mensal'}]),{n:'Estimativa anual'},...(compacta?[]:['Observação']),'Ações'],rows.filter(r=>r.estado===id).map(r=>[U.celula(`<div class="desc">${U.avatar(r.estabelecimento)}<div><strong>${e(r.estabelecimento)}</strong><small>${e(r.instituicao)} · ${e(r.id_conta?nomeConta(r.id_conta):'Conta não informada')}${compacta?`<br>${C.brl(r.valor_medio_brl)} por mês · ${observacao(r)}`:''}</small></div></div>`,r.estabelecimento),...(compacta?[]:[U.celula(C.brl(r.valor_medio_brl),r.valor_medio_brl)]),U.celula(`<span class="valor-cell">${C.brl(r.custo_anual_estimado_brl)}</span>`,r.custo_anual_estimado_brl),...(compacta?[]:[U.celula(observacao(r),r.meses_observados)]),acoes(r,id)]),'',{rodape:['Total anual estimado',...(compacta?[]:['']),C.brl(C.somar(rows.filter(r=>r.estado===id),'custo_anual_estimado_brl')),...(compacta?[]:['']),'']});
 const meses=C.agrupar(future.map(r=>({...r,mes:r.data.slice(0,7)})),'mes').sort((a,b)=>a.nome.localeCompare(b.nome));
 const maxMes=Math.max(...meses.map(g=>g.total??0),1);
 const agenda=meses.length?`<div class="agenda">${meses.map(g=>U.botao(`<span class="mes">${e(C.mesBR(g.nome))}</span><span class="track"><i style="width:${Math.max(2,(g.total??0)/maxMes*100)}%"></i></span><span class="valor">${C.brl(g.total)}<small>${C.numero(g.quantidade)} ${g.quantidade===1?'parcela':'parcelas'}</small></span>`,()=>drill(`Futuros conhecidos · ${C.mesBR(g.nome)}`,{},g.linhas),'agenda-mes',`aria-label="${e(C.mesBR(g.nome))}: ${e(C.brl(g.total))} em ${g.quantidade} parcelas. Ver futuros"`)).join('')}</div><p class="agenda-total"><span>Total futuro conhecido</span><strong>${C.brl(C.somar(future))}</strong></p>`:U.vazio('Nenhuma parcela futura informada pelas instituições.');
 const recolhivel=(id,titulo,sub)=>{const n=rows.filter(r=>r.estado===id).length;return `<details class="panel recolhivel"><summary><div class="panel-head"><div><h2>${e(titulo)}</h2><p class="sub">${e(sub)} · ${C.numero(n)} ${n===1?'item':'itens'}</p></div>${U.icone('abrir')}</div></summary><div class="conteudo">${tabela(id)}</div></details>`;};
 return `<div class="cards">${U.metrica('Recorrências confirmadas',String(ativas.length),anual?`${C.brl(anual/12)} por mês, em média`:'Por conta monitorada')}${U.metrica('Custo anual estimado',C.brl(anual),'Média observada × 12; não é previsão garantida')}${U.metrica('A revisar',String(sugestoes.length),sugestoes.length?'Padrões esperando sua decisão':'Nenhuma sugestão pendente',sugestoes.length?'amber':'',sugestoes.length?()=>document.querySelector('#sugestoes')?.scrollIntoView({behavior:'smooth',block:'start'}):null)}${U.metrica('Parcelas futuras conhecidas',C.brl(C.somar(future)),`${future.length} lançamentos da fonte`)}</div>`
  +`<p class="section-note">${U.icone('info')}<span>Detecção histórica e compromissos conhecidos, independentes do período do cabeçalho. Banco e conta continuam filtrados. Ausência de cobrança não encerra uma recorrência; parcelas não entram na detecção.</span></p>`
  +`<div class="grid2 grid-largo">${U.painel('Confirmadas','Estado aplicado ao estabelecimento neste banco, inclusive outras contas.',tabela('ativa',true))}${U.painel('Calendário futuro conhecido','Apenas parcelas já informadas pela instituição. Não inclui novas compras nem projeta assinaturas.',agenda)}</div>`
  +`<div id="sugestoes">${U.painel('Sugestões para revisar','Padrões observados, ainda não confirmados. A decisão vale para o estabelecimento no banco inteiro.',tabela('sugestao'))}</div>`
  +recolhivel('ignorada','Ignoradas','Marcadas como não recorrentes')+recolhivel('encerrada','Encerradas','Recorrências que acabaram');
}
// Patrimônio: primeiro o líquido e a série; depois a composição e as posições.
function patrimonio(){
 const fs=estado.filtros,allC=C.filtrar(dados.stg_contas,fs,false),allI=fs.conta?[]:C.filtrar(dados.stg_investimentos,{banco:fs.banco},false);
 const contas=C.posicoesEm(allC,fs.fim,'id_conta'),invest=C.posicoesEm(allI,fs.fim,'id_investimento');
 const caixa=contas.filter(r=>r.tipo==='BANK'&&r.moeda==='BRL'),divida=contas.filter(r=>r.tipo==='CREDIT'&&r.moeda==='BRL'),aplic=invest.filter(r=>r.moeda==='BRL');
 const rows=[...contas,...invest],invalidos=rows.filter(r=>r.moeda!=='BRL'||r.saldo===null),c=C.somar(caixa,'saldo'),i=C.somar(aplic,'saldo'),d=C.somar(divida,'saldo'),liquido=rows.some(r=>r.saldo!==null&&r.moeda==='BRL')?(c??0)+(i??0)-(d??0):null;
 const serie=C.serieComparavel(allC.filter(r=>r.tipo==='BANK'||r.tipo==='CREDIT'),allI).filter(r=>r.data<=fs.fim);
 const datasDisponiveis=rows.map(r=>r.data_posicao).filter(Boolean).sort();
 const snapshot=datasDisponiveis.length?`${C.dataBR(datasDisponiveis[0])} a ${C.dataBR(datasDisponiveis.at(-1))}`:'Sem posição até esta data';
 const showPositions=data=>{const cs=allC.filter(r=>r.data_posicao===data),is=allI.filter(r=>r.data_posicao===data);U.abrirDialog('Posições em '+C.dataBR(data),U.tabela(['Instituição','Conta / investimento','Moeda',{n:'Saldo'}],[...cs,...is].map(r=>[U.bancoNome(r.instituicao),e(r.nome),e(r.moeda),r.saldo===null?'Não disponível':C.numero(r.saldo)])));};
 const variacaoSerie=serie.length>=2?serie.at(-1).total-serie[0].total:null;
 const todasAntigas=contas.length>0&&contas.every(r=>r.data_posicao&&r.data_posicao<manifesto.data_referencia);
 const ativos=(c??0)+(i??0),escala=Math.max(ativos,d??0,1);
 const parte=(v,cor)=>v?`<i style="width:${Math.max(.5,v/escala*100)}%;background:${cor}"></i>`:'';
 const componente=(rotulo,valor,nota,cor)=>`<article class="metric"><span class="marcador" style="background:${cor}"></span><span class="label">${e(rotulo)}</span><strong>${e(valor)}</strong><small>${e(nota)}</small></article>`;
 const total=`<section class="panel patrimonio-total"><article class="metric"><span class="label">${e(invalidos.length?'Patrimônio BRL parcial':'Patrimônio líquido monitorado')}</span><strong>${U.valorGrande(C.brl(liquido))}</strong><small>${variacaoSerie===null?'Contas bancárias + investimentos − dívida dos cartões':`<span class="${variacaoSerie>=0?'pos':'neg'}">${variacaoSerie>=0?'+':''}${e(C.brl(variacaoSerie))}</span> desde ${e(C.dataBR(serie[0].data))}`}</small></article><div class="composicao"><div class="composicao-linha"><span>Ativos</span><span class="composicao-barra">${parte(c,'var(--acento)')}${parte(i,'#b5ceff')}</span></div><div class="composicao-linha"><span>Dívida</span><span class="composicao-barra">${parte(d,'var(--negativo)')}</span></div><div class="composicao-itens">${componente('Saldo em contas bancárias',C.brl(c),'Posições, não despesas','var(--acento)')}${componente('Investimentos',C.brl(i),'Somente posições em BRL','#b5ceff')}${componente('Dívida em cartões',C.brl(d),'Saldo devedor informado pela fonte','var(--negativo)')}</div></div></section>`;
 const historico=U.painel('Histórico de posições','Somente retratos completos em BRL com o mesmo conjunto de contas e investimentos. Clique num ponto para ver as posições.',serie.length<2?U.vazio('Ainda não há dois retratos completos comparáveis. O período não permite inferir uma tendência.'):U.graficoLinha(serie.slice(-12),showPositions));
 return `<div class="patrimonio-topo">${total}${historico}</div>`
  +U.aviso(`Posições monitoradas até ${C.dataBR(fs.fim)}. Datas disponíveis: ${snapshot}. Contas bancárias + investimentos − dívida dos cartões. Contas de investimento são exibidas, mas seu saldo não é somado novamente.`,true)
  +(fs.conta?U.aviso('Investimentos não possuem vínculo de conta na fonte e foram omitidos neste filtro de conta.',true):'')
  +(invalidos.length?U.aviso(`Patrimônio BRL parcial: ${invalidos.length} posições ausentes até a data, sem saldo ou em outra moeda. Consulte os valores originais abaixo.`):'')
  +U.painel('Contas e cartões',todasAntigas?`Valores originais por moeda. Todas as posições são anteriores à data de referência (${C.dataBR(manifesto.data_referencia)}).`:'Valores originais por moeda. Confira a data de cada posição.',U.tabela(['Instituição','Conta','Tipo','Data',{n:'Saldo'},{n:'Limite disponível'}],contas.map(r=>[U.celula(U.bancoNome(r.instituicao),r.instituicao),e(r.nome),e(C.rotulo(r.tipo)),U.celula(`${r.posicao_ausente?'Sem posição até esta data':C.dataBR(r.data_posicao)}${!todasAntigas&&r.data_posicao&&r.data_posicao<manifesto.data_referencia?'<small>Posição anterior à data de referência</small>':''}`,r.data_posicao),U.celula(r.saldo===null?'Não disponível':`<span class="valor-cell">${dinheiro(r.saldo,r.moeda)}</span>`,r.saldo),U.celula(r.limite_disponivel===null?'Não informado':dinheiro(r.limite_disponivel,r.moeda),r.limite_disponivel)])))
  +U.painel('Investimentos monitorados','Sem soma entre moedas. A data de referência da fonte pode diferir da captura.',U.tabela(['Instituição','Investimento','Captura / referência',{n:'Saldo'},{n:'Rendimento'}],invest.map(r=>[U.celula(U.bancoNome(r.instituicao),r.instituicao),U.celula(`${e(r.nome)}<small>${e(C.rotulo(r.tipo))}</small>`,r.nome),U.celula(r.posicao_ausente?'Sem posição até esta data':`${C.dataBR(r.data_posicao)}<small>Referência ${C.dataBR(r.data_referencia)}</small>`,r.data_posicao),U.celula(r.saldo===null?'Não disponível':`<span class="valor-cell">${dinheiro(r.saldo,r.moeda)}</span>`,r.saldo),U.celula(r.rendimento===null?'Não informado':dinheiro(r.rendimento,r.moeda),r.rendimento)])));
}
const exemplosSQL=[
 ['Gasto por mês','SELECT substr(data, 1, 7) AS mes, sum(valor_brl) AS total_brl, count(*) AS lancamentos\nFROM gastos_analiticos\nGROUP BY mes\nORDER BY mes DESC'],
 ['Maiores estabelecimentos','SELECT estabelecimento, sum(valor_brl) AS total_brl, count(*) AS vezes\nFROM gastos_analiticos\nGROUP BY estabelecimento\nORDER BY total_brl DESC\nLIMIT 20'],
 ['Exclusões por motivo','SELECT motivo_exclusao, count(*) AS lancamentos, sum(valor_brl) AS total_brl\nFROM transacoes_analiticas\nWHERE motivo_exclusao IS NOT NULL\nGROUP BY motivo_exclusao\nORDER BY lancamentos DESC']
];
// SQL: o editor já pronto, com o esquema ao lado e Ctrl+Enter para executar.
function ferramentas(){
 const preencher=sql=>{const campo=document.querySelector('#sql-code');campo.value=sql;campo.focus();};
 const executar=async()=>{const out=document.querySelector('#sql-result');try{const sql=C.sqlSeguro(document.querySelector('#sql-code').value);out.innerHTML=`<div class="panel"><p class="sub"><span class="spinner"></span> Consultando…</p></div>`;const inicio=performance.now();const rows=await consultar(/^(describe|explain)\b/i.test(sql)?sql:`SELECT * FROM (${sql}) AS consulta LIMIT 501`);const tempo=Math.round(performance.now()-inicio);const keys=Object.keys(rows[0]??{}),numericas=new Set(keys.filter(k=>{const v=rows.find(r=>r[k]!=null)?.[k];return typeof v==='number';}));const texto=v=>v==null?'NULL':typeof v==='number'?v.toLocaleString('pt-BR',{maximumFractionDigits:6}):typeof v==='object'?JSON.stringify(v):v;out.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Resultado</h2><p class="sub">${rows.length>500?'Primeiras 500 linhas; resultado limitado.':C.numero(rows.length)+(rows.length===1?' linha':' linhas')} · ${C.numero(tempo)} ms</p></div></div>${U.tabela(keys.map(k=>numericas.has(k)?{n:k}:k),rows.slice(0,500).map(r=>keys.map(k=>U.celula(e(texto(r[k])),r[k]==null?null:typeof r[k]==='object'?JSON.stringify(r[k]):r[k]))),'mono-tabela')}</section>`;}catch(err){out.innerHTML=U.aviso(err.message);}};
 const tabelasEsquema=Object.keys(manifesto.arquivos).sort();
 return `<div class="bancada"><aside class="esquema" aria-label="Tabelas disponíveis"><h2>Tabelas</h2><div class="esquema-lista">${tabelasEsquema.map(n=>U.botao(`${e(n)}<span>${C.numero(manifesto.linhas?.[n]??0)}</span>`,()=>preencher('SELECT * FROM '+n+' LIMIT 100'),'',`title="Consultar ${e(n)}"`)).join('')}</div></aside><div>`
  +U.painel('Bancada SQL','SELECT · WITH · DESCRIBE · EXPLAIN · até 500 linhas exibidas',`<label class="field">Consulta<textarea id="sql-code" class="code" rows="8" spellcheck="false">SELECT categoria, sum(valor_brl) AS total_brl
FROM gastos_analiticos
GROUP BY categoria
ORDER BY total_brl DESC</textarea></label><div class="actions">${U.botao(U.icone('executar')+'Executar consulta',executar,'primary','id="sql-executar"')}<span class="atalho"><kbd>Ctrl</kbd> + <kbd>Enter</kbd></span><span class="exemplos"><span class="atalho">Exemplos</span>${exemplosSQL.map(([nome,sql])=>U.botao(e(nome),()=>preencher(sql),'small')).join('')}</span></div>`)
  +`<div id="sql-result" aria-live="polite"></div></div></div>`
  +U.aviso('Consulta somente leitura sobre a publicação carregada. Esta ferramenta não aplica os filtros globais automaticamente.',true);
}
document.addEventListener('keydown',U.tratarTeclasAbas);
document.addEventListener('keydown',event=>{if(event.target.id==='sql-code'&&event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();document.querySelector('#sql-executar')?.click();}});
document.addEventListener('click',async event=>{try{await U.tratarClique(event);}catch(err){U.toast(err.message);}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='fatura-mes'){estado.faturas.mes=el.value;estado.faturas.selecao='__total__';render();document.querySelector('#fatura-mes')?.focus();return;}if(el.dataset.ids){for(const id of JSON.parse(el.dataset.ids))selecionar(id,el.checked);}if(el.closest('#filtros')){const name=el.name,value=el.value,anteriores={...estado.filtros};if((name==='inicio'||name==='fim')&&!value){U.toast('Informe uma data válida.');atualizarFiltros();return;}if(name==='mes'){if(value)Object.assign(estado.filtros,C.limitesMes(value),{fim:value===manifesto.data_referencia.slice(0,7)?manifesto.data_referencia:C.limitesMes(value).fim});}else estado.filtros[name]=value;if(name==='banco')estado.filtros.conta='';if(estado.filtros.inicio>estado.filtros.fim){estado.filtros=anteriores;atualizarFiltros();U.toast('A data inicial deve ser anterior à data final.');return;}estado.drill=null;estado.pagina=0;estado.selecionadas.clear();atualizarFiltros();render();document.querySelector(`#filtros [name="${name}"]${name==='modo'?':checked':''}`)?.focus();}});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='explore-form'){const f=new FormData(event.target);estado.busca=f.get('busca');estado.categoria=f.get('categoria');estado.ordem=f.get('ordem');U.limparOrdemTabela('transacoes:explorar:transacoes');estado.pagina=0;render();}else U.tratarSubmit(event).catch(err=>U.toast(err.message));});
