document.querySelector('#fechar-dialog').addEventListener('click',()=>document.querySelector('#detalhe').close());document.querySelector('#detalhe').addEventListener('click',event=>{if(event.target===event.currentTarget)event.currentTarget.close();});document.querySelector('#recarregar').addEventListener('click',inicializar);document.querySelector('.brand').addEventListener('click',event=>{event.preventDefault();irPara('resumo');});
